// CONFIG — esta instancia de n8n bloquea $env en nodos Code, así que va literal aquí
const API_URL = 'http://IP_TAILSCALE_RASPBERRY:8000/api';
const API_KEY = 'PON_AQUI_TU_API_KEY';
const CHAT_ID = 0; // sustituye por tu chat_id de Telegram

const staticData = $getWorkflowStaticData('global');

async function apiGet(path) {
  const res = await fetch(`${API_URL}${path}`, { headers: { 'X-API-Key': API_KEY } });
  if (!res.ok) throw new Error(`API ${path} -> HTTP ${res.status}`);
  return res.json();
}

function fmtNum(n, d = 0) {
  return (n === null || n === undefined) ? '—' : Number(n).toFixed(d);
}

const ALARM_LABELS = {
  rfl_power_alarm: 'RFL Power',
  fwd_power_alarm: 'FWD Power',
  exc_power_alarm: 'EXC. Power',
  temp_combiner_alarm: 'Temp. Combiner',
  permanent_fail_alarm: 'Permanent Fail',
  ext_interlock_alarm: 'Ext. Interlock',
  control_unit_power_alarm: 'Control Unit Power',
};

let status;
let apiError = null;
try {
  status = await apiGet('/status');
} catch (e) {
  apiError = e.message;
}

if (apiError) {
  return [{
    json: {
      action: 'dashboard',
      chatId: CHAT_ID,
      hasPinned: !!staticData.pinnedMessageId,
      text: `⚠️ <b>Amplificador FM</b>\nNo se pudo consultar la API: ${apiError}`,
    },
  }];
}

const events = [];
const wasConnected = staticData.lastConnected === true;
const nowConnected = !!status.connected;

// --- Texto del dashboard ---
const lines = [];
lines.push('📻 <b>Amplificador FM — esRadio Albacete</b>');
if (nowConnected) {
  const target = status.transport === 'serial' ? status.device : `${status.host}:${status.port}`;
  lines.push(`🟢 Conectado (${status.transport}) — <code>${target}</code>`);
} else {
  lines.push(`⚪ Desconectado${status.last_error ? ` — ${status.last_error}` : ''}`);
}

const m = status.measurements;
const a = status.alarms;

if (m) {
  lines.push('');
  lines.push(`⚡ FWD: <b>${fmtNum(m.fwd_power_w)} W</b> · DC: ${fmtNum(m.vdc_volts, 1)} V`);
  const amps = m.idc_amps.map((c, i) => `A${i + 1}:${c}${m.current_alarms && m.current_alarms[i] ? '⚠️' : ''}`).join('  ');
  lines.push(`🔋 ${amps}`);
}

if (a) {
  const activas = Object.entries(ALARM_LABELS).filter(([k]) => a[k]).map(([, v]) => v);
  lines.push('');
  lines.push(activas.length ? `🚨 <b>Alarmas:</b> ${activas.join(', ')}` : '✅ Sin alarmas activas');
}

lines.push('');
lines.push(`<i>Actualizado: ${new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid' })}</i>`);

events.push({
  json: {
    action: 'dashboard',
    chatId: CHAT_ID,
    hasPinned: !!staticData.pinnedMessageId,
    text: lines.join('\n'),
  },
});

// --- Detección de eventos (transición de alarmas / conexión) ---
if (a) {
  const prevAlarms = staticData.lastAlarms || {};
  for (const [key, label] of Object.entries(ALARM_LABELS)) {
    const now = !!a[key];
    const before = !!prevAlarms[key];
    if (now && !before) {
      events.push({ json: { action: 'alerta', chatId: CHAT_ID, text: `🚨 <b>Alarma activada:</b> ${label}` } });
    } else if (!now && before) {
      events.push({ json: { action: 'alerta', chatId: CHAT_ID, text: `✅ <b>Alarma resuelta:</b> ${label}` } });
    }
  }
  staticData.lastAlarms = a;
}

if (nowConnected && !wasConnected) {
  events.push({ json: { action: 'alerta', chatId: CHAT_ID, text: `🟢 <b>Conectado</b> al amplificador (${status.transport})` } });
} else if (!nowConnected && wasConnected) {
  events.push({ json: { action: 'alerta', chatId: CHAT_ID, text: `⚪ <b>Desconectado</b> del amplificador${status.last_error ? ` — ${status.last_error}` : ''}` } });
}
staticData.lastConnected = nowConnected;

return events;

// CONFIG — esta instancia de n8n bloquea $env en nodos Code, así que va literal aquí
const API_URL = 'http://IP_TAILSCALE_RASPBERRY:8000/api';
const API_KEY = 'PON_AQUI_TU_API_KEY';
const AUTHORIZED_USERS = [0]; // sustituye por los Telegram user IDs autorizados
const CONFIRM_TIMEOUT_MS = 60 * 1000;
const RISKY_LABELS = {
  arrancar: 'ARRANCAR el transmisor',
  parar: 'PARAR el transmisor',
  reset: 'resetear las alarmas',
};
const RISKY_ENDPOINTS = { arrancar: '/start', parar: '/stop', reset: '/reset' };

const staticData = $getWorkflowStaticData('global');
const update = $input.first().json;

async function apiCall(path, method = 'GET', body = null) {
  const res = await fetch(`${API_URL}${path}`, {
    method,
    headers: { 'X-API-Key': API_KEY, 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);
  return data;
}

function reply(chatId, messageId, text) {
  return { json: { action: 'reply', chatId, replyToMessageId: messageId, text } };
}

// ---------- Callback (botón Confirmar/Cancelar) ----------
if (update.callback_query) {
  const cb = update.callback_query;
  const fromId = cb.from.id;
  const chatId = cb.message.chat.id;
  const messageId = cb.message.message_id;
  const queryId = cb.id;

  const ack = { json: { action: 'callbackAck', queryId } };

  if (!AUTHORIZED_USERS.includes(fromId)) {
    return [ack, { json: { action: 'editConfirm', chatId, messageId, text: '🔒 No autorizado.' } }];
  }

  const pending = staticData.pendingConfirm;
  const [kind, nonce] = String(cb.data || '').split(':');

  if (!pending || pending.nonce !== nonce || Date.now() > pending.expiresAt) {
    return [ack, { json: { action: 'editConfirm', chatId, messageId, text: '⌛ Confirmación caducada o inválida. Repite el comando.' } }];
  }

  staticData.pendingConfirm = null;

  if (kind === 'cancel') {
    return [ack, { json: { action: 'editConfirm', chatId, messageId, text: `❎ ${RISKY_LABELS[pending.action]} — cancelado.` } }];
  }

  try {
    const data = await apiCall(RISKY_ENDPOINTS[pending.action], 'POST');
    return [ack, { json: { action: 'editConfirm', chatId, messageId, text: `✅ ${RISKY_LABELS[pending.action]} — hecho (${data.raw_hex || data.ack_hex || 'ok'}).` } }];
  } catch (e) {
    return [ack, { json: { action: 'editConfirm', chatId, messageId, text: `❌ Error al ${RISKY_LABELS[pending.action]}: ${e.message}` } }];
  }
}

// ---------- Mensaje de texto ----------
const msg = update.message;
if (!msg || !msg.text) return [];

const fromId = msg.from.id;
const chatId = msg.chat.id;
const messageId = msg.message_id;
const text = msg.text.trim();

if (!AUTHORIZED_USERS.includes(fromId)) {
  return [reply(chatId, messageId, '🔒 No autorizado.')];
}

const [cmdRaw, ...args] = text.split(/\s+/);
const cmd = cmdRaw.toLowerCase().replace(/^\//, '').split('@')[0];

try {
  switch (cmd) {
    case 'ayuda':
    case 'help':
      return [reply(chatId, messageId,
        '<b>Comandos disponibles</b>\n' +
        '/estado — resumen del amplificador\n' +
        '/alarmas — detalle de alarmas\n' +
        '/log [n] — últimas n lecturas (por defecto 5)\n' +
        '/subir — +50W\n' +
        '/bajar — −50W\n' +
        '/potencia 40|50|60|70|80|90 — preset de potencia\n' +
        '/maxima — potencia máxima\n' +
        '/arrancar — Start (pide confirmación)\n' +
        '/parar — Stop (pide confirmación)\n' +
        '/reset — reset de alarmas (pide confirmación)\n' +
        '/conectar host puerto — conectar por red (ser2net)\n' +
        '/conectar serial /dev/ttyUSB0 — conectar por puerto serie directo\n' +
        '/desconectar — cerrar la conexión'
      )];

    case 'estado': {
      const data = await apiCall('/summary');
      return [reply(chatId, messageId, data.text)];
    }

    case 'alarmas': {
      const a = await apiCall('/alarms');
      const ALARM_LABELS = {
        rfl_power_alarm: 'RFL Power', fwd_power_alarm: 'FWD Power', exc_power_alarm: 'EXC. Power',
        temp_combiner_alarm: 'Temp. Combiner', permanent_fail_alarm: 'Permanent Fail',
        ext_interlock_alarm: 'Ext. Interlock', control_unit_power_alarm: 'Control Unit Power',
      };
      const activas = Object.entries(ALARM_LABELS).filter(([k]) => a[k]).map(([, v]) => v);
      return [reply(chatId, messageId, activas.length ? `🚨 Alarmas activas: ${activas.join(', ')}` : '✅ Sin alarmas activas')];
    }

    case 'log': {
      const n = Math.max(1, Math.min(parseInt(args[0], 10) || 5, 50));
      const data = await apiCall(`/history?limit=${n}`);
      if (!data.points.length) return [reply(chatId, messageId, 'Sin lecturas en el histórico todavía.')];
      const lines = data.points.map(p => {
        const m = p.measurements;
        return `${p.timestamp} — FWD ${m ? m.fwd_power_w : '—'}W, DC ${m ? m.vdc_volts : '—'}V`;
      });
      return [reply(chatId, messageId, `<b>Últimas ${data.points.length} lecturas:</b>\n` + lines.join('\n'))];
    }

    case 'subir': {
      const data = await apiCall('/power/up', 'POST');
      return [reply(chatId, messageId, `⬆️ Potencia subida (${data.raw_hex}).`)];
    }

    case 'bajar': {
      const data = await apiCall('/power/down', 'POST');
      return [reply(chatId, messageId, `⬇️ Potencia bajada (${data.raw_hex}).`)];
    }

    case 'potencia': {
      const pct = parseInt(args[0], 10);
      if (![40, 50, 60, 70, 80, 90].includes(pct)) {
        return [reply(chatId, messageId, 'Uso: /potencia 40|50|60|70|80|90')];
      }
      const data = await apiCall('/power/set', 'POST', { percent: pct });
      return [reply(chatId, messageId, `🎚️ Potencia fijada al ${pct}% (${data.raw_hex}).`)];
    }

    case 'maxima': {
      const data = await apiCall('/power/max', 'POST');
      return [reply(chatId, messageId, `🔺 Potencia máxima fijada (${data.raw_hex}).`)];
    }

    case 'conectar': {
      let body;
      if (args[0] === 'serial') {
        if (!args[1]) return [reply(chatId, messageId, 'Uso: /conectar serial /dev/ttyUSB0')];
        body = { device: args[1] };
      } else {
        const [host, port] = args;
        if (!host || !port) return [reply(chatId, messageId, 'Uso: /conectar <ip> <puerto>  ó  /conectar serial <device>')];
        body = { host, port: parseInt(port, 10) };
      }
      const data = await apiCall('/connect', 'POST', body);
      const target = data.transport === 'serial' ? data.device : `${data.host}:${data.port}`;
      return [reply(chatId, messageId, `🔌 Conectado — ${target} (${data.transport}).`)];
    }

    case 'desconectar': {
      await apiCall('/disconnect', 'POST');
      return [reply(chatId, messageId, '🔌 Desconectado.')];
    }

    case 'arrancar':
    case 'parar':
    case 'reset': {
      const nonce = String(Date.now());
      staticData.pendingConfirm = { action: cmd, nonce, expiresAt: Date.now() + CONFIRM_TIMEOUT_MS };
      return [{
        json: {
          action: 'sendConfirm',
          chatId,
          replyToMessageId: messageId,
          text: `⚠️ ¿Seguro que quieres <b>${RISKY_LABELS[cmd]}</b>? Caduca en ${CONFIRM_TIMEOUT_MS / 1000}s.`,
          confirmData: `confirm:${nonce}`,
          cancelData: `cancel:${nonce}`,
        },
      }];
    }

    default:
      return [reply(chatId, messageId, `Comando no reconocido: ${cmdRaw}. Usa /ayuda.`)];
  }
} catch (e) {
  return [reply(chatId, messageId, `❌ Error: ${e.message}`)];
}
